// Helper para llamar a la API de Loyverse
async function callLoyverseApi(endpoint: string, options: { method?: string; body?: any; token?: string } = {}) {
  const token = options.token || activeLoyverseToken;
  if (!token) {
    throw new Error("LOYVERSE_TOKEN_NOT_CONFIGURED");
  }

  const url = `https://api.loyverse.com/v1.0${endpoint.startsWith("/") ? endpoint : `/${endpoint}`}`;
  const headers: Record<string, string> = {
    Authorization: `Bearer ${token}`,
    "Content-Type": "application/json",
  };

  const fetchOptions: RequestInit = {
    method: options.method || "GET",
    headers,
  };

  if (options.body && options.method !== "GET" && options.method !== "HEAD") {
    fetchOptions.body = typeof options.body === "string" ? options.body : JSON.stringify(options.body);
  }

  const response = await fetch(url, fetchOptions);
  const text = await response.text();
  let data: any;
  try {
    data = text ? JSON.parse(text) : {};
  } catch {
    data = { raw: text };
  }

  if (!response.ok) {
    const error: any = new Error(data?.message || `Loyverse API error ${response.status}`);
    error.status = response.status;
    error.data = data;
    throw error;
  }

  return data;
}

// Helper para traer todos los items con paginación
async function fetchLoyverseAllItems(token?: string): Promise<any[]> {
  let cursor: string | null = null;
  const allItems: any[] = [];
  do {
    const endpoint = `/items?limit=250${cursor ? `&cursor=${cursor}` : ""}`;
    const data = await callLoyverseApi(endpoint, { token });
    if (data.items && Array.isArray(data.items)) {
      allItems.push(...data.items);
    }
    cursor = data.cursor || null;
  } while (cursor);
  return allItems;
}

// Helper para traer todos los registros de inventario con paginación
async function fetchLoyverseAllInventory(token?: string): Promise<any[]> {
  let cursor: string | null = null;
  const allInventory: any[] = [];
  do {
    const endpoint = `/inventory?limit=250${cursor ? `&cursor=${cursor}` : ""}`;
    const data = await callLoyverseApi(endpoint, { token });
    if (data.inventory_levels && Array.isArray(data.inventory_levels)) {
      allInventory.push(...data.inventory_levels);
    }
    cursor = data.cursor || null;
  } while (cursor);
  return allInventory;
}

