// 7. Sincronización Unificada (Items + Inventario de Noise Urban + SKUs + Colores + Tallas)
app.get("/api/loyverse/sync", async (req: Request, res: Response) => {
  try {
    if (!activeLoyverseToken) {
      return res.json({
        configured: false,
        products: [],
        message: "Ingresa tu Token de Loyverse en el Panel de Administración",
      });
    }

    const targetStoreId = await getDefaultStoreId();

    const [items, invLevels, categoriesData] = await Promise.all([
      fetchLoyverseAllItems(),
      fetchLoyverseAllInventory(),
      callLoyverseApi("/categories").catch(() => ({ categories: [] })),
    ]);

    const categories = categoriesData.categories || [];

    // Mapear niveles de inventario específicamente para la tienda Noise Urban (Urbannoise)
    const inventoryMap = new Map<string, number>();
    for (const lvl of invLevels) {
      if (lvl.variant_id && (!targetStoreId || lvl.store_id === targetStoreId)) {
        const current = inventoryMap.get(lvl.variant_id) || 0;
        inventoryMap.set(lvl.variant_id, current + (lvl.in_stock || 0));
      }
    }

    // Estructurar items con variantes, SKUs, colores, tallas e inventario
    const syncedItems = items.map((item: any) => {
      const colorsSet = new Set<string>();
      const sizesSet = new Set<string>();

      const variants = (item.variants || []).map((v: any) => {
        const stockInPos = inventoryMap.get(v.variant_id) ?? 0;
        const override = inventoryOverrides[v.sku] ?? inventoryOverrides[v.variant_id];
        const finalStock = override !== undefined ? override : stockInPos;

        const size = (v.option1_value || "").trim();
        const color = (v.option2_value || "").trim();
        if (size) sizesSet.add(size);
        if (color) colorsSet.add(color);

        const storePrice = v.stores?.find((s: any) => s.store_id === targetStoreId)?.price;
        const variantPrice = (storePrice !== undefined && storePrice !== null) ? storePrice : (v.default_price ?? v.price ?? 0);

        return {
          variant_id: v.variant_id,
          sku: v.sku || `SKU-${v.variant_id.substring(0, 6)}`,
          barcode: v.barcode,
          price: variantPrice,
          default_price: v.default_price,
          stores: v.stores,
          cost: v.cost || 0,
          option1_value: v.option1_value,
          option2_value: v.option2_value,
          option3_value: v.option3_value,
          size,
          color,
          in_stock: finalStock,
        };
      });

      const totalStock = variants.reduce((sum: number, v: any) => sum + (v.in_stock || 0), 0);

      return {
        id: item.id,
        name: item.item_name,
        category_id: item.category_id,
        category_name: categories.find((c: any) => c.id === item.category_id)?.name || "General",
        description: item.description,
        image_url: item.image_url,
        variants,
        availableColors: Array.from(colorsSet),
        availableSizes: Array.from(sizesSet),
        totalStock,
        storeId: targetStoreId,
      };
    });

    res.json({
      configured: true,
      storeId: targetStoreId,
      count: syncedItems.length,
      items: syncedItems,
      categories,
      syncedAt: new Date().toISOString(),
    });
  } catch (error: any) {
    res.status(500).json({ error: error.message });
  }
});


